    "description": "帮助孩子识别脸部表情，认知情绪。为社交能力的发展奠定基础。\n这是一本“婴儿情绪认知启蒙第一书”。全书只有简单的图形和线条，展示开心、伤心、生气、调皮等各种脸部表情。画面极度简洁，对比鲜明，非常适合婴儿视觉发展。\n我们家宝宝起初貌似并不太感兴趣，也是经常抢过书啃咬，不过我们计划等他稍微大几个月，再配合一些手指玩偶编故事，继续进行情绪互动。",
