    "title": "抱抱",
    "ageRange": "0-3岁",
    "description": "这本书只有简简单单不断重复的抱抱，却展示了浓浓的亲子情，用拥抱来告诉孩子我爱你！\n《抱抱》这本书咱们群里的妈妈分享很多遍了，我们用这个本书是学习抱的不同感受我娃现在1岁，还不会表达情绪，也不会说我难过，我想抱抱.\n所以我们给他设计三种抱法，轻轻抱（安抚）紧紧抱（开心）转一圈抱（兴奋）\n每次念到抱抱就换一种抱法，宝宝特别喜欢。他现在会主动把小手伸过来，示意想抱抱，还会拍我的肩膀2下。这是他会表达的第一步",
