    "title": "吃水果吧/吃蔬菜吧/好吃的蔬菜从哪来",
    "ageRange": "0-3岁",
    "description": "水果蔬菜翻翻书的（感觉适合小不点娃）图比较简单也不炸眼，也没有太多细致费眼的地方，可能因为翻的过程有趣？\n水果蔬菜翻翻书——画风简洁不抽象，色彩温和不扎眼，孩子边翻还能边认识蔬菜水果，我家书架回读率第一名，纸张厚度适宜不会有paper cut的风险，反复翻看（只要不暴力撕扯）都不会有褶皱或者破损掉色的问题。然后就是别的姐妹也提到过的科普偷偷翻系列——我这套是朋友给我的，也是我家书架回读率前三。这套也是内置翻页的书，字儿比较多内容很丰富，大点的孩子可以看内容，小点的孩子可以翻翻页看图识物。但是哪怕只停留在看图识物的阶段，书中的内容也足够丰富，小娃的阅读兴趣也能被调动起来。",
