    "title": "Leslie Patricelli 宝宝硬页书（Tubby / Blankie / Hop! Hop! / On My Potty）",
    "ageRange": "1岁+",
    "description": "**适读年龄：**1–3岁（亲子共读 1–3 岁；作为如厕/自理启蒙读物尤佳）。\n共通特点：用词简洁、重复句式、情境贴近日常（洗澡、安抚物、节日、如厕），非常适合习惯培养与情绪识别。\nTubby：围绕洗澡流程（洗→玩→擦干→穿衣→睡前）与身体部位词汇，建立可预测的自理节奏。\nBlankie：安全毯主题，涉及分离焦虑、安抚、自我调节，帮助建立睡前/外出仪式感。\nHop! Hop!：复活节情境（染彩蛋、寻彩蛋、兔耳朵等），轻松介绍节日习俗与简单秩序。\nOn My Potty（英版题名；美版常见 Potty）：如厕启蒙，将身体意识与如厕步骤（坐、等、擦、冲、洗手）幽默化，降低焦虑。",
