    "description": "每本里面六首歌，经典歌曲，学校里每天唱的，他会跟着做动作。感应圆点触摸出声，再触摸停止\n这套书之前群里有妈妈推荐过，大概就是按一下就会唱一段儿歌。我本来买回来的目的是想让他熟悉一下英文的儿歌，这样去幼儿园了不会一切都很陌生（毕竟睡前故事之类我是真的不知道本地人会讲啥…）。现在这个书成了宝宝的音乐播放器，他会在想听背景音乐的时候点一下然后去玩一会儿然后再点一下[捂脸] 当然这个书也有缺点。一个是质量确实不是很好，在破损程度不如usborne的有声书的时候播放就出现问题了。一个是儿歌都只有一段，没唱完老母亲听着难受。再就是有部分儿歌唱的有点跑调…？但是瑕不掩瑜，崽喜欢老母亲就喜欢！",
    "categories": [
      "认知"
    ],
    "type": "book",
    "ageGroup": "0-2岁",
    "mainTab": "认知启蒙"
