    "title": "Usborne 有声书系列",
    "ageRange": "1岁+",
    "description": "• 这个系列不用太多赘述了，经典的典中典，对婴儿时期的视觉、听觉刺激非常好，促进多感官发展，触摸、听、看同时进行。\n• Usborne 的有声书是我们每天都要翻开的书。只要轻轻一碰，动物叫声、汽车声、乐器声等等就会跳出来，既是书也是一个小小的感官启蒙玩具。他还很喜欢模仿里面的发音，尤其是各种小动物的叫声和唱歌的。\n• 我个人觉得还是Usborne比my first touch and noisy sound book系列比如noisy farm这些，更适合小娃自己点按。noisy的按钮位置看起来不明确并且需要使劲才能按动，小娃的手指小很容易找不到准确的位置，经常还是需要大人帮忙去按，不过内容都是真实图片，对认知帮助也蛮大的，也有触摸的区域，适合小时候大人陪娃一起，但是像我家的暴躁急火炉自己按不动或者没按对地方会发脾气，我们帮忙都不行",
