    "title": "就像它那样",
    "ageRange": "1岁+",
    "description": "这本来自意大利的经典左右脑开发绘本，用孩子能理解的语言告诉我们——人类的许多发明，其实都源自对自然的观察。螃蟹的钳子启发了剪刀，蜘蛛网启发了吊床，蜗牛的壳启发了房车……这是一本引导孩子“从观察到思考”的绘本，非常适合进行亲子共读。孩子在读的过程中，会自然地模仿书中的比较和思辨方式。这本书属于一整套意大利逻辑思维训练工具书，我家目前只有这一册。欢迎有其他同系列绘本的妈妈也来分享一下，看要不要入整套！",
