    "description": "推荐理由：画面丰富、有趣，覆盖场景全面，可以帮助孩子学习词汇。\nStephen Cartwright创作的Usborne经典作品，包含了各类繁忙场景中1000个值得一看的事物，每个场景都旨在帮助读者快速、愉快地学习、复习或丰富词汇。据说三代孩子都通过这本有趣的书建立了他们的基本词汇（比如我家爸爸，是他说他小时候有本这样的书，他觉得特别有趣，然后一通找，找到了这本）。每一页还有一只小黄鸭等着孩子去找，孩子一边翻一边找鸭子，可以和大人一起看、学习词汇，也可以自己翻看研究各类场景。我儿子通过这本书学会了很多词语，当然最喜欢的就是找鸭子。你能找到The Kitchen这一页里的小鸭子吗？",
