    "ageRange": "1岁+",
    "description": "通过实拍图，讲了一个小男孩要出去遛狗结果找不到鞋子，在家里翻箱倒柜的故事\n我们宝宝15个月大，不太能明白翻箱倒找鞋子这回事，但是非常喜欢里面开冰箱和找猫咪那两页（其他页面因为我们不太允许她在家里翻箱倒柜所以她不太能relate）\n喜欢开冰箱：每天早上外婆都要给她从冰箱里拿鸡蛋煮着吃，这个书冰箱那页也有一盒鸡蛋，会给妈妈指鸡蛋\n喜欢找猫咪：她本来就很喜欢小月龄那本小红书里面一模一样的猫咪（喜欢到早就翻烂了），每次说“宝宝给妈妈找找猫咪在哪”，她都能理解是要去书里翻猫咪，甚至会到那一页停下来，专门拿我的手或者示意让我亲自翻起来（so sweet）\n我们暂时没有特意引导读书，就把书放在小书架和爬爬垫各处让宝宝自己玩，她目前似乎不太要看书，更喜欢把书扔来扔去，但这本宝宝真的一眼爱上，当天就玩坏了最容易坏的那一页，值得推荐",
