    "description": "内容大概就是bear的朋友在榨果汁的时候不小心把bear的衣服弄脏，然后bear收集脏衣服放到洗衣机洗然后晾干的故事，然后是有各种很简单的小机关，比如榨汁机榨果汁可以转起来，洗衣机滚筒可以转起来，然后倒洗衣液，这些都是有一些小机关，我家娃我觉得就是根据这本书学会怎么用洗衣机的，然后就会在我们家洗衣机那鼓捣半天，然后我逛超市时候顺便就给他买了一个洗衣机的玩具，我个人感觉这两个一起用，能不那么废洗衣机，但是这个洗衣机玩具，我觉得滚筒转起来的时候噪音稍微有一丢丢大，总的来说，很推荐这本书，这本书在我们家也是几乎战损的状态",
