    "title": "再见，妈妈的奶",
    "ageRange": "1岁+",
    "description": "• 围绕断奶／宝宝告别母乳离乳的阶段，非常适合宝宝成长初期，很适合断奶前后共读，帮助宝宝理解“告别妈妈的奶”是件自然又温暖的事。\n• 这本日本绘本的视觉及叙事风格非常简单，温柔，细腻，帮助宝宝理解“我在长大”“我不只是喝妈妈的奶了”这些概念，有助于情绪上的准备。\n• 我家宝宝是大概16个月的时候彻底断母乳，在这之前，从13个月左右大的时候我们就开始去一起读这本书，最开始的时候他也并不理解这到底是什么，只是喜欢看里面的图画，随着日积月累并且在日常的吃饭也会告诉他书里面的话比如你现在可以吃很多很多饭你要长大啦等等，不知道有没有这个的铺垫原因后续断奶过程还是非常丝滑的。在这之后，他还是会翻开这本书拍拍我的胸脯或者指一下说“奶”，并且挥手bye bye，然后里面的小动物他也特别喜欢，比如里面的小象小兔子，看到后还会自己发散思考去找其他书里有这些动物的书并模仿叫声",
