    "description": "官方建议年龄0-3但是我娃现在5岁了还很爱，可以说是我娃最喜欢的绘本之一了！\n书本比较小，厚纸板，每一页颜色鲜艳，画风我个人很喜欢，主人公是只有一根头发穿尿布的小宝宝，每本书有一个生活中很常见的主题，比如洗澡，剪头发，长牙，potty training ，吃饭，宠物，还有关于大小，多少，安静吵闹，好好吃饭等，非常实用贴近生活。作者也是挺幽默，我娃特别喜欢里面光屁股裸奔的桥段[破涕为笑] yummy yucky 里面有冰淇淋好吃，太多冰淇淋不好吃，不好吃那页吃太多冰淇淋变绿了，我娃到现在每次想吃很多冰淇淋的时候就问我妈妈我变绿了么[旺柴] 反正挺好玩的一套书，娃喜欢妈妈也喜欢",
