    "title": "我的时间书",
    "ageRange": "3岁+",
    "description": "当时我好奇长大了要怎么给她教时间和看表随手买的。买来的时候她五六个月大，那时候也就摸摸，看大人摆弄，但是这个封面的两个指针是一转会有一点吱嘎声的，所以她经常看我们转指针，听着那声音笑。后来八九个月的时候开始伸出食指去拨弄指针，翻到后面去抠/撕那些小翻页。是一本以为会闲置好几年，没想到翻玩率还蛮高的一本，目前小翻页们被撕得所剩无几了。如果大一点（估计三四岁？）的孩子用这本书，效果肯定会好很多，能真的学时间和表盘。",
