    "ageRange": "1岁+",
    "description": "这本书是在本群种草的，在此之前我已经买过一些类似于first 100 words的书，娃都没有兴趣，但是这本很神奇，娃在十月龄左右拿到后就非常喜欢看（也不知道在看什么，那时候不会说话也不会指，就是安安静静地来回翻看）。现在十五月龄了，我们依然每天拿出来看一会，学会了不少词。可能是因为这本书采用了照片而非卡通，并且照片选得很妙，都是典型角度，并且细节丰富。",
