    "title": "《My first book》系列里面的BABY SHARK",
    "ageRange": "0.5岁+",
    "description": "在我的宝宝四五个月的时候就收到朋友送的这一套《My first book》系列里面的BABY SHARK，她从六七个月开始可以坐就玩一直到现在快一岁半还是很感兴趣。\n这个整个都是布艺制品，所以小宝宝也不会撕坏，里面每页都有很多可以互动的环节，比如说可以移动里面的鲨鱼来达到锻炼手部精细程度的目的。同时里面也会有一些环节，比如说其中有是他们给其中一只鲨鱼过生日，里面的生日蛋糕是可以移动的，旁边还会有一些可以打开的礼物，礼物里面可能会有一些小鱼缸，这样其实是可以给小一点的宝宝自己编造一些对应的故事情节可以让宝宝更有观察力和专注力。\n这个一系列书有不同的主题，我朋友送的这一套是鲨鱼系列，我偶尔会配合那首baby shark的歌曲一起放给她听，可以顺便培养一点律动感。\n目前我的宝宝可以一个人自己玩，硬控半小时左右没问题！非常省妈！\n推荐给大家。\n唯一不好的可能就是这里面有些小零件宝宝会拿下来玩，经常就会找不到了。我之前看到群里有另一个妈妈建议说可以在书后面粘一个宜家的密封袋小玩具可以顺手放进去，这样就不会丢，我觉得这个方法也很好！",
