    "title": "Baby all science",
    "ageRange": "2-4岁",
    "description": "面向低幼儿的科学启蒙绘本，图画生动有趣。\n虽然是韩国出的，但有英文版，内容设计的还是非常有意思的。不是普通的故事书，而是融汇了各种机关的机关书。而且大部分都是硬纸板，非常抗造。\n譬如说这个本比大小，动物都是pop up出来的，非常直观的对比了动物的大小尺寸\n配对儿同款手套袜子，可以通过转动齿轮来找到一模一样的款式\n手指书字书，搭配手指来体现数字的概念\n吹风的这本，里面就有一个小小的风扇，可以手动转动\n前后的概念这本，有一个可以活动的小人，鼓励孩子来摆一摆位置，学习什么是前面和后面",
