    "title": "安的种子",
    "ageRange": "3岁+",
    "description": "相对于给孩子的绘本，更像是一本让家长读完自省的绘本。\n 我们的手里都有一颗种子，错误的时间揠苗助长无视自然规律卷生卷死；或是温室里太过无微不至的“窒息”监护；都无法让这颗种子生根发芽茁壮成长。\n 先着眼忙好自己的事，眼前的事，尊重种子的意愿，合适的时间，适当的照顾，勇敢的放手，静待花开。",
