    "ageRange": "2-4岁",
    "description": "情绪与共情：当孩子伤心时，一只兔子静静陪伴，教会倾听的力量。\n这本书很不错，是一本关于处理情绪的书，小男孩辛苦搭的积木倒了，该怎么办. 不同的动物过来提出自己的解决方法，对动物的性格特点其实也有一个体现，比如鸵鸟说藏起来假装什么都没发生、熊的办法是大叫……最后兔子来了，静静地陪着他，听他发泄，一直都没有离开，最后他的情绪处理好了，和兔子一起准备重新搭新的.这是孩子在日常经常会出现的现象，辛苦做的东西坏了. 教育孩子如何好好生气，也教育家长如何接纳和处理情绪. 句子简单，y1孩子自读完全没问题，我只负责翻书和参与讨论。\n延伸阅读：         \nRabbit 系列：No! Said Rabbit 的续集是 Ready! Said Rabbit，讲小兔子积极主动的一面。",
