    "title": "Topsy and Tim 系列",
    "ageRange": "2.5岁+",
    "description": "这套书可能有点小众？但也算是英国经典童书系列。每一本都围绕孩子日常生活里可能遇到的新场景或新经历，比如去幼儿园、看医生、搬新家、结识新朋友等等。故事温馨又真实，能帮助孩子提前了解、熟悉这些情境，减少陌生感。我们家娃尤其喜欢跟着 Topsy 和 Tim 的经历去联想自己的生活，每次读完我们就会聊聊“我是不是也这样”“下次会不会也这样”。 我们在今年insert week给她安排每天跟着topsy tim打卡活动，例如露营，溜冰，游泳, 农场, 动物园 等等。 BBC iplayer里面也有topsy tim真人剧 也是很推荐。",
