    "description": "Llama穿好了红色睡衣，爬上了自己的小床，完成了一系列睡前仪式后，妈妈Llama放心的离开了，Baby Llama会乖乖睡觉吗？\n阅读的时候可以带着这样的疑问和孩子一起把故事读下去，Mama Llama去楼下忙了，Baby Llama的内心小剧场也开始了。妈妈什么时候才能把手头的事情忙完回来陪伴Baby Llama呢？如果房间太黑了会不会有可怕的东西你呢？Baby Llama一点也睡不着，她发出了各种声音，妈妈能听得见吗？她会回来吗？\n这是一本非常贴近孩子们生活的绘本，睡前仪式，讲故事，对黑暗和独自睡眠的恐惧，对妈妈的期待和依赖，是每个孩子几乎每天都正在经历的事情。小朋友们无论是能够独立阅读本书，还是需要在爸爸妈妈的陪伴下阅读，听爸爸妈妈读，应该都能够体会到Baby Llama的心情。\n同样的绘本也有中文点读版，遗憾的是翻译本身没有突出故事本身的韵律感，跟英文版比起来没有朗朗上口的感觉。英文版的Rhyme让整个故事像一首歌谣，更适合小朋友们喜欢的阅读节奏，加上羊驼本身就是一个很有趣诙谐的故事形象，插画师对人物的表情刻画也很到位，为阅读提供了很多可以延申和讨论的超出画面之外的内容。\nLlama Llama系列还有很多和现实生活有关的小故事也很适合特别喜欢这个故事的小朋友去做相关的延伸阅读，Youtube上也有这个系列的动画片。",
