    "id": "792ebaab",
    "title": "Usborne 的 why do I need to wash?",
    "ageRange": "2岁+",
    "description": "适用于2-6岁左右的科普绘本，一问一答的插画翻翻页，通俗易懂，很直观。大多数小孩不理解为什么洗手，很多时候是大人要求小孩洗手（我家的就是），每次上完厕所都告诉我“妈咪，我已经冲了厕所，洗了手了，你有没有听到呀？”，就好像是完成任务要报告给我一样。\n其中还讲到动物也会有自己的方式去洗澡，小孩带着好奇心去寻找答案。（小孩印象最深刻）\n书里还会讲到“细菌是什么？”“它们看不见却会让人生病”，用简单易懂的语言和图画，把抽象的卫生知识转化为孩子能理解的形象。（小孩知道这个单词但是应该还不理解）\n总得来说，互动性强，孩子在翻页的过程中，也是在“玩”中学习，它既能满足孩子的好奇心，又能在潜移默化中培养良好的卫生习惯。",
