    "description": "这是一本被低估的书，挺厚一本，细节满满，商店街总共有37家商店，美食店、文具店、书店、布行等等。每家商店都有很多客人，他们在做着不同的事情，可以引导孩子去描述，我一开始都会带着她看，给她讲所有我能看到的东西，拓展词汇量，到后来她就自己开始翻着逛，虽然她还不能完全表达清楚她想说的，但是在尽可能的讲她能看到的所有细节，好处是商店种类多，她每逛一家都在使劲动脑检索词库，在想这是什么😅很努力",
