    "id": "79b0e62d",
    "title": "宫西达也的恐龙系列丛书",
    "ageRange": "2岁+",
    "description": "适合恐龙迷们，画风妈妈觉得很丑很丑很吓人，但是娃很喜欢。可以买对应的毛绒玩具配合书一起共读，娃很喜欢。一起读完有时候会被故事和道理感动的落泪，故事很感人，很有教育意义。有不同恐龙的主题故事，例如霸王龙，慈母龙，翼龙，蛇颈龙等。文字简单，也适合做桥梁书。\n推荐理由：\n\t•\t寓教于乐：借助恐龙这一孩子普遍喜爱的题材，进入情感教育和价值观教育的领域。孩子容易被恐龙吸引，家长也可借此引发深度对话。\n\t•\t情感共鸣强：弱小、孤独、误解、守护、告别……这些情节元素丰富，又非常具有人性化。\n\t•\t图文结合佳：图像丰富、角色表情及动作细腻；文字简单但意味深远，适合亲子共读。\n\t•\t系列多册：适合长期阅读、收集、形成系列感。",
