    "ageRange": "3岁+",
    "description": "《恐龙大陆》是一套很棒的恐龙主题绘本 。它在“让孩子感受世界”“引发恐龙兴趣”方面做得出色。对于热爱恐龙、喜欢探险、喜欢图画书的孩子来说，是一套值得收藏、反复阅读的绘本。“恐龙大陆”并不仅仅是单纯的恐龙画册或科普书，而是将 冒险故事 与 科普知识融合在一起。通过恐龙爸爸大角培养恐龙小角勇气与坚韧品格，孩子在读故事的同时，也能认识不同种类的恐龙、了解它们的生活习性与时代背景。",
