    "description": "给娃挑第一本绘本时候我的要求是颜色鲜艳并贴近生活，我在国内某小红书主播无意间发现的这套书，这套书包含了四本：Trees, Friut, Flowers and Vegetables。这套书标注的是4-8岁，但作为小娃娃的彩色绘本也毫无问题，甚至在今年夏天我表姐带着我侄女（12岁）从国内来英国玩的时候，我表姐让我侄女好好看看这套书。比如：Fruit这本书的最开始讲的是“apple”，我拍了几张照片给大家看看，包含了苹果的颜色，切开的苹果以及苹果树的生长等等；最搞笑的是草莓部分，我家夕夕半岁多的时候看这本书每次翻到草莓页都要去舔一舔[Lol]",
