    "description": "讲的是小兔子向狼面包师学习烘焙的故事.故事里小兔子失败多次仍努力坚持认真学习烘焙，让狼面包师由一开始的不耐烦到认可从而最后成为搭档. 而狼面包师虽然很凶但仍然教会了小白兔最好吃的面包.\n 画风细腻内容治愈，能做出美味面包的狼也打破了传统上对负面形象的认知，有助于提高孩子对于一样事物一尘不变的刻板影响.\n这本书适合2.5+的宝宝看",
    "categories": [
      "故事"
    ],
    "type": "book",
    "ageGroup": "2-4岁",
    "mainTab": "故事绘本"
