    "title": "Grace说系列 （Grace 说耐心；专心；恒心；感恩）",
    "ageRange": "2.5岁+",
    "description": "相信很多妈妈都知道《你就是孩子最好的玩具》这本书，里面提到很重要的一个概念就是通过情感引导的方式帮助孩子学习大量情感类词汇，这样孩子才能表达出来，并且和我们沟通，而不是只会大喊大叫。我们要播一颗种子（耐心、专心），并不断做积极的强化。（具体细节请参看原书）\n这套Grace说系列既是孩子的学习绘本，也是家长的实操手册，语言简洁，不断重复强化。平时生活中，也可以按照书中的模式来对孩子进行情感引导。",
