    "description": "续集《妈妈一定来接我》讲述一个小女孩米拉（Mila）在幼儿园里开心地学习、交朋友，但她心中有一个小小的担心：放学的时候，妈妈会来接她吗？她不断地问妈妈：“妈妈，你真的会来吗？要是遇到…怎么办？”而妈妈则用充满想象力的语言，一次次承诺：“当然啦，我们不是说好了嘛”——无论是工作像山一样高、刮大风、交通堵塞、小桥塌了、小河结冰、甚至小红帽请妈妈吃蛋糕……妈妈都用各种比喻和温暖的语言告诉米拉：不管发生什么事情，妈妈都会准时来接你回家。【其实我很希望主题是爸妈一定来接我，而不是妈妈】",
