    "description": "故事讲的是小姑娘玛丽无意间发现了一只住在她家墙另一边的小老鼠，和她成为朋友的暖心故事。仿佛生活在平行时空的伙伴，她们一起长大，同样都去上学，离开家，成立自己的新家庭，并有了自己的孩子。后来，玛丽的女儿和小老鼠的女儿再次在玛丽的新家重逢。\n很喜欢这本书的画风和插画师的想象力。玛丽家的鸡蛋盒变成了小老鼠家的沙发，手表被当成了时钟，邮票变成了装饰画，非常可爱。用一个不同的视角去看待日常的用品，想着原来还可以这么用。即使作为大人，也觉得这样微缩的世界很奇妙，小朋友们更是如此吧。\n正好再推荐一下两个治愈系的瑞典电影《鼠洞里的好朋友》和吉卜力的动画《借东西的小人阿莉埃缇》。",
