    "title": "The Dinosour next door",
    "ageRange": "3岁+",
    "description": "推荐一下这本书，超级温暖超级感动！去年出版的，最开始是在书店上看到，因为我小孩很喜欢恐龙，就多注意了一下，但是当时也没有翻看，也没有买，不知道内容是讲什么。今天娃先看，看哭了；我想我来看看，我也看哭了[流泪][流泪]\n它讲述女孩Liz隔壁住了Mr Wilson先生，日常在蛋糕店上班，会做非常美味的蛋糕。但是明明Liz看着他就是一只brachiosaurus or diplodocus，但是周围所有人都没有觉得奇怪，都说就是Mr Wilson。某天Liz决定跟踪Mr Wilson，果然发现Mr Wilson走进来森林，吃树叶等等。其实Mr Wilson早就知道Liz在跟踪自己，他一点也不生气，还带着Liz一起看到了真正的恐龙世界……哪知Liz之前告诉的博物馆工作人员也跟踪了Mr Wilson，发现他真的是恐龙，于是把他带回了博物馆……",
