    "description": "小鼠啵啵系列包含各种不同类型，机关书、立体场景游戏书、贴纸书，我家娃从三岁翻到现在六岁了也会拿出来看，不是那种你念她听的书，是娃自己能玩起来的那种，拉一拉、翻一翻、立体小场景，能安静自己玩很久自己讲故事的。内容也很生活化，睡觉、上幼儿园、逛商店、看电影、天气、动物这些，语言非常简单，上reception学phonics后完全可以小朋友自己读。配合机关，小朋友参与感很强，不容易腻。我个人感觉2岁到3岁闭眼入玩具书和立体场景，3岁以后自然科学和生活体验那套也很香。印刷到纸张到绘画风格和做工都很不错！属于我自己也很喜欢的一套。",
