    "title": "How to be a Doctor /How to be a Vet",
    "ageRange": "4岁+",
    "description": "How to be a Doctor\n**适读年龄：**4–8岁（亲子共读 4–6 岁；6–8 岁可自主/跟读）。\n简介：以门诊/体检为线索，认识医生与护士的分工、常见设备（听诊器、体温计、血压计）、就诊流程与卫生习惯（洗手、佩戴口罩），并通过情境化故事缓解孩子对就医的紧张，培养同理心与基本健康认知。\nHow to be a Vet\n**适读年龄：**4–8岁（亲子 4–6；6–8 跟读/自主）。\n简介：围绕宠物与小型动物诊疗，介绍动物基本需求（食物、清洁、运动）、体检流程与简单护理（称重、观察症状、用药安全），强调动物福利与对生命的尊重，帮助孩子建立责任感与情绪调节（分离焦虑、担心生病等）。",
