    "ageRange": "5岁+",
    "description": "这套书是我们80后熟悉的童话大王郑渊洁写给儿子的教材（背景是因为他觉得中国的学校教育他看不上，所以自己在家教他儿子，很有个性的一个人）。\n书推荐年龄：小学。我打算娃上小学开始和娃一起讨论式读完并且后面希望她能看图画和简单中文来强化安全意识。\n书分为：安全之星，科技天使，危难之光，生命之盾，假期贴士，性格养成\n由于书还没有转运来，我先借小红书图片分钟一下里面一些语录和插图，不得不感叹下养娃的过程我不断怀念自己的童年，有鞠萍姐姐讲故事，有中外童话，每天守着中央六台看动画片～",
