    "ageRange": "4-6岁",
    "description": "当时我们完全是被封面这只软萌到不行的北极狐宝宝吸引，翻开书后更是惊喜满满，里面全是各种动物宝宝的高清大图，比如北极狐、小鹿、小企鹅等孩子们会非常喜欢的小动物。画风写实，笔触温柔，只是看着就让人心情很好。\n等宝宝再大一点时，我们应该能一起用这本书认识动物、讲故事，很适合亲子共读。它是大开本，纸张和印刷质感也都很棒，放在家里当摆设都很好看，没事了大人翻一翻也很有意思。\n这是一系列书的一册，还有海洋生物，恐龙，等等其他主题，等娃长大后来继续探索。",
