    "ageRange": "4岁+",
    "description": "绘本书适合4岁以上，动画片适合3岁以上（2岁半也能看但是应该看不太懂）. 书和动画片都很推荐！非常温暖的故事也是非常有爱的一家人。强烈安利给每一个有娃的家庭！\n它讲的不是“教孩子要怎样”，生活不止一种可能。bluey的爸妈从不扫兴，随时随地陪孩子把生活变成游戏；姐妹之间会吵架、会吃醋，但也会认真照顾彼此的情绪。它告诉孩子：你可以有小情绪，可以不开心，可以说不，可以拒绝，不用为了讨好别人而委屈自己。\n很多情节真的拍得特别有智慧，教孩子怎么面对成长、面对分别、面对“我好像不如别人”的时刻，讲得很轻，但后劲很大。\n我女儿是三岁开始中英文版本反复刷 N 遍，看动画的过程中居然自然学会了很多中文词汇。四岁以后开始买书，到现在还是会时不时自己翻出来看。不是那种看一阵就腻的 IP，是真的会陪着孩子一起长大的那种，我自己也超级喜欢看！",
