    "ageRange": "6岁+",
    "description": "不知道咱们这个群有没有孩子学拼音，如果有的话，给大家推荐一套。蒲蒲兰出得《佐罗力》。我们馆里的孩子基本上就读这一套拼音就差不多熟悉了。但是大家购买的时候记得甄别。只买主系列一套就行了，其他版本的，都是来凑数凑热度的。\n《佐罗力》特别可爱，是个捣蛋大王，或者梦想当一个捣蛋大王，孩子们内心都会喜欢这样的设定。但是这个小家伙，捣蛋了67次都没能成功，原因都是他为了朋友或者爱放弃了捣蛋的机会选择了正义。因此从内容和价值观上，是符合筛选条件的。另外，拼音是用正音校准过的，不会出现市场上那些乱七八糟的东西做出来的书，几页一个错误。。。，给大家推荐一下",
