    "ageRange": "8岁+",
    "description": "一个清冷的早晨，以捡废品为生的老爷爷，捡到了此生最大的宝贝——一个婴儿。对于无儿无女的老爷爷和老奶奶来说，这是上天恩赐的礼物。他们虽然清贫，却给了这个取名“丑丑”的男孩最无私的爱。而在爷爷奶奶去世后，邻居葵花妈、学校程校长，尤其是年轻的班主任左老师，向丑丑张开了爱的怀抱；胆小的好朋友陈樱、同样家逢不幸的江大丫、终于懂事的小霸王林生……他们陪伴丑丑一起，走向了崭新的生活。“即使出生在尘埃里，也要勇敢地生长在阳光下。\n孩子的反馈是很温馨感人的故事。",
