    "ageRange": "8岁+",
    "description": "无聊、枯燥、抵触、约束……对学校生活的种种负面标签，在《疯狂学校》里将被一一粉碎，这里没有权威，校长竟扮成火鸡、在旗杆上倒吊着、把头发涂成橘色、还打算扮成圣诞老人从楼顶上跳下来、甚至当众去亲吻一头猪……许多出人意料不按常理出牌的举动，在疯狂学校里却成为常态。\n这套类似国内《米小圈》那样的校园生活口水书。虽说没有什么深度，但孩子觉得好玩爱读，我就允许她读了。\n相反，在英国学生中很火的多克日记 Dork's Diaries，我们却不希望孩子读。",
