    "title": "计客的井字棋",
    "ageRange": "3岁+",
    "description": "上层是电子的，有三种模式，单人对战（vs电脑），双人对战，记忆模式。前面两种模式到落第四次棋子的时候，会灭掉最前面落的那次棋子，所以不会形成死局，没人赢就可以一直下，一直落子时候就灭掉最先下的棋子（不知道解释清楚了没）。记忆模式就是它会显现出一个亮灯顺序，亮完你来重复一遍，难度递增。\n 下层是传统井字棋的升级版，因为可以大吃小。棋子分为三个尺寸，大的可以套住（吃掉）小的，从而让那个位置变成你自己手中棋子的颜色。所以在传统“占位”的基础上，还要考虑别人是不是可以把你吃掉来完成ta的连线。亲测四五岁可以完全get规则，我家两岁半那个老看着哥哥玩，也基本get了规则（但思路上肯定不如大一点孩子完整）。 \n 体积也不大，带出门玩也不是很占地方。",
    "categories": [
      "逻辑-空间"
    ],
    "type": "game",
    "ageGroup": "2-4岁",
    "mainTab": "教具桌游"
