    "title": "Plus Plus积木",
    "ageRange": "3-6岁",
    "description": "适用年龄\n1. 大号（Midi Size）： 适合 3-6岁 的幼儿。积木块更大，方便小手抓握，防止误吞，是低龄儿童入门的最佳选择。\n2. 小号（Mini Size）： 适合 5-12岁及以上 的儿童和甚至成人。积木块更小，可以拼搭出更精细、更复杂的模型，挑战性更强，也深受拼搭爱好者和减压人群的喜爱。\n虽然我闺女买的时候才4岁，但直接买的是小号，我本意是便于携带，飞机上，火车上长途旅行酒店里都可以拿出来。所以这个前提是不再往嘴里放玩具的年纪再玩。\n玩法就很多样了\n1️⃣可以按图纸拼，类似乐高\n2️⃣平面图创意拼，想拼图形都可以试着凑出来\n3️⃣立体拼。",
