    "description": "一个适合2岁+的亲子动物拼图，各种小动物妈妈和宝宝，背面还有英文和中文名称。娃会非常热心地帮小动物们找妈妈（我儿子两岁多，找到妈妈对他来说就是头等大事）。很好玩，推荐给大家！",
