    "ageRange": "2岁+",
    "description": "培养规则意识、明白指令、水果配件大、质感好\nHABA经典游戏，规则简单，掷骰子，丢到颜色拿对应的水果，丢到乌鸦就乌鸦前进一步，玩家要在小乌鸦到达果园之前，合作摘走水果。玩好之后，还可以点数、比多少，水果配件也可以作为role play的道具。我觉得这一套桌游非常适合孩子培养规则意识和合作意识，因为很简单，但是需要几个玩家一起才能摘走所有的水果！我儿子超爱的桌游之一！",
