    "title": "To Market去市场 Einkaufen",
    "ageRange": "2岁+",
    "description": "帮助形状颜色认知、语言表达、财商启蒙\nHABA经典游戏，4张购物清单，每个物品对应不同钱币，掷骰子然后根据清单去市场购物，帮助孩子认识每个货摊的分类、理解物品买卖、价格的概念，还可以通过角色扮演，让孩子学会礼貌用语。我儿子一开始很喜欢去买东西，玩了一阵之后更喜欢当shop keeper，学着大人的样子说“Good morning Madam/Sir! How can I help?”“The bread costs one golden coin!” “Here you go, thank you for your purchase, have a nice day!”之类的，我觉得特别有意思。",
