    "id": "a2999e59",
    "title": "迷你便携打印机",
    "ageRange": "",
    "description": "我主要看中它这几点：\n· 技术方便：热敏打印，无需墨水，手机直连。\n· 使用贴心：打印纸带背胶，直接粘贴，做手帐/笔记无敌方便。\n· 用途广泛：从配合学校的作业，到家里的日记、旅行手记，都能用上。\n· 孩子喜欢：即时打印照片能极大激发孩子的记录热情。我们组团出游时，几个孩子因为这个爱上了写日记，每天都比着看谁记得更精彩。\n注： 对于热敏打印机，经朋友好心提醒，我想我有责任提醒一下大家，热敏纸里的显色剂可能不是含BPA就是含BPS。大家如果选择使用要注意洗手，不要和食物接触。实际上各种超市小票大家也要注意，接触后勤洗手，避免和食物接触。不是洪水猛兽，但是要科学地降低风险，减少不必要的身体损伤。谢谢。",
