    "description": "大月龄小月龄都是一个强推。这个相对于磁力片更好上手，首先他比较轻不容易夹手，其次他本来就是3D的一个造型，每个角都有磁力很容易可以搭成各种造型，相对于磁力片很难从2D变成3D导致小朋友有挫败感这个就会让他们很快可以有成就感从而更加有兴趣。我们家从好小一岁就开始玩，一直玩到了现在三岁多可以直接照着造型拼或者自己设计造型专注玩半小时。重点就是一定一定一定要买足够的量，我们原来是买了一大组 他小时候还是玩的大一点兴趣没那么多，后来我们又买了两组，能搭的造型就很多了他就可以一直玩。最后这个我看还有人用来做教具的，就是什么两个三角形拼起来是正方形啥的感觉用途很多。我家还有一个那种磁吸钓鱼的，可以用那个来掉这个磁力块 反正玩法很多！！！强推",
