    "ageRange": "2岁+",
    "description": "80 90后的宝妈谁小时候能没听过故事盒啊！\n“亲爱的小朋友，当你打开这个小小的故事盒，就会发现里面有许多许多神奇美妙的故事，这些故事呀！你妈妈听过，你奶奶听过，你奶奶的奶奶也听过，不信？你问他们去！好～咱们的故事呀，现在就要开始啦！”\n非常经典的“鞠萍姐姐”声音，不同角色区别配音，特别是小娃娃的配音带点口音不要更惟妙惟肖了。都是非常经典的儿童故事，但是讲述的方式真是绘声绘色，背景配音音效也生动形象，一下子就能把听众带入进那个场景里。不得不说这套故事盒，真是完完全全秒杀现在市面上的各种故事机和喜马拉雅上的故事频道。孩子小的时候为了给她网上找讲故事的，试了多少都不满意，最后还是找了怀旧店铺入了全套磁带+磁带机。经典好故事版本值得代代相传给孩子给孙子！\n（不一定要买磁带，喜马拉雅上有几盒磁带的录播，哔哩哔哩也有一些。后续我也会抽时间把故事录下来上传到网上分享给大家）",
