    "id": "c5d8f19f",
    "title": "蛤蟆先生去看心理医生",
    "ageRange": "",
    "description": "**中文译本：**建议 13岁—成人（初中高年级起）。低龄儿童不建议独立阅读。\n英文原著（Counselling for Toads）：建议 16岁—成人（含较多心理学术语与抽象概念）。\n更适合作为家长/老师/青少年的情绪与沟通读物，而非学龄前或低年级儿童的绘本。\n简介\n借用《柳林风声》中的角色讲述蛤蟆陷入抑郁并接受心理咨询的过程，核心围绕交互分析（TA）——“父母我—成人我—儿童我”三自我状态、沟通脚本与关系模式。以故事化方式科普情绪识别、沟通方式、改变习惯等主题。",
