    "id": "9bc99637",
    "title": "Unconditional Parenting: Moving From Rewards and Punishments to Love and Reason",
    "ageRange": "",
    "description": "这本书从根本上挑战“孩子必须表现好、才值得被爱”的传统育儿观念。孩子的一个基本需求就是被“无条件爱”，即使犯错、失败，也知道自己被接纳。书中不仅分析了传统方式的问题，还提供了很多实用策略，帮助父母从“控制孩子”转向“与孩子一起成长”，理解孩子的需求、感受、观点。",
